/**
 * Unix seconds.
 */
createdAt: number; 
/**
 * Unix seconds of the last successful import with this format.
 */
lastUsedAt: number; 
/**
 * The shipped preset whose headers this layout now matches, filled on every read (a preset
 * always wins over a learned format) and stored as `null`.
 */
